            MATCH (ni2)-[hp:HAS_PART {is_spare: false}]->(p:Part)
            RETURN sum(hp.qty) AS nested2_parts
        }
        CALL {
            WITH ni2
            MATCH (ni2)-[cm2:CONTAINS_MINIFIG]->(m2:Minifig)-[:HAS_INVENTORY]->(mi2:Inventory)
            WITH m2, mi2, cm2.qty AS mf2_qty
            CALL {
                WITH mi2
                MATCH (mi2)-[hp:HAS_PART {is_spare: false}]->(p:Part)
                RETURN sum(hp.qty) AS mf2_parts
            }
            RETURN coalesce(sum(mf2_qty * mf2_parts), 0) AS nested_mf2_total
        }
        RETURN coalesce(sum(set2_qty * (nested2_parts + nested_mf2_total)), 0) AS nested_set2_total
    }
    RETURN coalesce(sum(set_qty * (nested_parts + nested_mf_total + nested_set2_total)), 0) AS set_total
}
CALL {
    WITH i
    MATCH (i)-[cm:CONTAINS_MINIFIG]->(m:Minifig)-[:HAS_INVENTORY]->(mi:Inventory)
    WITH m, mi, cm.qty AS mf_qty
    CALL {
        WITH mi
        MATCH (mi)-[hp:HAS_PART {is_spare: false}]->(p:Part)
        RETURN sum(hp.qty) AS mf_parts
    }
    RETURN coalesce(sum(mf_qty * mf_parts), 0) AS mf_total
}
RETURN part_total + set_total + mf_total AS total_parts
